import { SITE_NAME } from "@/lib/site";

/**
 * Brand lockup C: the Life Spread grid (nine card outlines, centre seat in
 * solid gold) with the serif "Card Blueprint" wordmark, a hairline and the
 * tracked tagline "+ CARDS ARE COORDINATES +".
 *
 * The header uses the horizontal arrangement of C (grid beside the wordmark
 * stack) because the stacked lockup is too tall for the header row; the
 * footer (`compact`) uses the stacked lockup. Text is outlined in the SVGs
 * (public/brand/logo-c-*.svg, generated by brand/make_logo_c.py) so the
 * wordmark renders identically without loading a web font.
 * Used in SiteHeader and SiteFooter.
 */
export function BrandLogo({ compact = false }: { compact?: boolean }) {
  return compact ? (
    <span className="brand-logo brand-logo-compact">
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        className="brand-logo-stacked"
        src="/brand/logo-c-stacked.svg"
        alt={SITE_NAME}
        width={727}
        height={523}
        loading="lazy"
        decoding="async"
      />
    </span>
  ) : (
    <span className="brand-logo">
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        className="brand-logo-horizontal"
        src="/brand/logo-c-horizontal.svg"
        alt={SITE_NAME}
        width={540}
        height={108}
        fetchPriority="high"
        decoding="async"
      />
    </span>
  );
}
